/* eslint-disable no-new-object, stdlib/require-globals, no-prototype-builtins */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Boolean = require( '@stdlib/boolean/ctor' );
var Number = require( '@stdlib/number/ctor' );
var Obj = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Obj, 'function', 'main export is a function' );
	t.end();
});

tape( 'the main export is the `Object` global', function test( t ) {
	t.strictEqual( Obj, Object, 'returns expected value' );
	t.end();
});

tape( 'the function returns an empty object when provided `null`', function test( t ) {
	var o;

	o = new Object( null );
	t.deepEqual( o, {}, 'returns expected value' );

	o = Object( null );
	t.deepEqual( o, {}, 'returns expected value' );

	t.end();
});

tape( 'the function returns an empty object when provided `undefined`', function test( t ) {
	var o;

	o = new Object( void 0 );
	t.deepEqual( o, {}, 'returns expected value' );

	o = Object( void 0 );
	t.deepEqual( o, {}, 'returns expected value' );

	t.end();
});

tape( 'the function returns a Number object when provided a number', function test( t ) {
	var o;

	o = new Object( 3 );
	t.strictEqual( o instanceof Number, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), 3, 'returns expected value' );

	o = Object( 3 );
	t.strictEqual( o instanceof Number, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), 3, 'returns expected value' );

	t.end();
});

tape( 'the function returns a String object when provided a string', function test( t ) {
	var o;

	o = new Object( 'beep' );
	t.strictEqual( o instanceof String, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), 'beep', 'returns expected value' );

	o = Object( 'beep' );
	t.strictEqual( o instanceof String, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), 'beep', 'returns expected value' );

	t.end();
});

tape( 'the function returns a Boolean object when provided a boolean', function test( t ) {
	var o;

	o = new Object( true );
	t.strictEqual( o instanceof Boolean, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), true, 'returns expected value' );

	o = Object( true );
	t.strictEqual( o instanceof Boolean, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), true, 'returns expected value' );

	o = new Object( false );
	t.strictEqual( o instanceof Boolean, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), false, 'returns expected value' );

	o = Object( false );
	t.strictEqual( o instanceof Boolean, true, 'returns expected value' );
	t.strictEqual( o.valueOf(), false, 'returns expected value' );

	t.end();
});

tape( 'the function returns an input value unchanged when provided an existing object', function test( t ) {
	var o1;
	var o2;

	o1 = {};
	o2 = new Object( o1 );
	t.deepEqual( o2, {}, 'returns expected value' );
	t.strictEqual( o1, o2, 'returns expected value' );

	o1 = {};
	o2 = Object( o1 );
	t.deepEqual( o2, {}, 'returns expected value' );
	t.strictEqual( o1, o2, 'returns expected value' );

	o1 = [];
	o2 = new Object( o1 );
	t.deepEqual( o2, [], 'returns expected value' );
	t.strictEqual( o1, o2, 'returns expected value' );

	o1 = [];
	o2 = Object( o1 );
	t.deepEqual( o2, [], 'returns expected value' );
	t.strictEqual( o1, o2, 'returns expected value' );

	t.end();
});

tape( 'the `constructor` prototype property is a reference to `Object`', function test( t ) {
	var o = new Obj( null );
	t.strictEqual( o.constructor, Obj, 'returns expected value' );
	t.end();
});

tape( 'the `hasOwnProperty` prototype method returns `true` for own properties', function test( t ) {
	var o;

	o = {
		'a': 1,
		'b': 2
	};
	t.strictEqual( o.hasOwnProperty( 'a' ), true, 'returns expected value' );
	t.strictEqual( o.hasOwnProperty( 'b' ), true, 'returns expected value' );
	t.end();
});

tape( 'the `hasOwnProperty` prototype method returns `false` for non-existent properties', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( o.hasOwnProperty( 'b' ), false, 'returns expected value' );
	t.end();
});

tape( 'the `hasOwnProperty` prototype method returns `false` for inherited properties', function test( t ) {
	var proto;
	var o;

	proto = {
		'a': 1
	};
	o = Obj.create( proto );
	t.strictEqual( o.hasOwnProperty( 'a' ), false, 'returns expected value' );
	t.end();
});

tape( 'the `isPrototypeOf` prototype method returns `true` when the object is in the prototype chain of the argument', function test( t ) {
	var proto;
	var o;

	proto = {
		'a': 1
	};
	o = Obj.create( proto );
	t.strictEqual( proto.isPrototypeOf( o ), true, 'returns expected value' );
	t.end();
});

tape( 'the `isPrototypeOf` prototype method returns `false` when the object is not in the prototype chain of the argument', function test( t ) {
	var o2;
	var o1;

	o1 = {
		'a': 1
	};
	o2 = {
		'b': 2
	};
	t.strictEqual( o1.isPrototypeOf( o2 ), false, 'returns expected value' );
	t.end();
});

tape( 'the `propertyIsEnumerable` prototype method returns `true` for own enumerable properties', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( o.propertyIsEnumerable( 'a' ), true, 'returns expected value' );
	t.end();
});

tape( 'the `propertyIsEnumerable` prototype method returns `false` for non-enumerable properties', function test( t ) {
	var o;

	o = Obj.defineProperty( {}, 'a', {
		'value': 1,
		'enumerable': false,
		'configurable': true,
		'writable': true
	});
	t.strictEqual( o.propertyIsEnumerable( 'a' ), false, 'returns expected value' );
	t.end();
});

tape( 'the `propertyIsEnumerable` prototype method returns `false` for inherited properties', function test( t ) {
	var proto;
	var o;

	proto = {
		'a': 1
	};
	o = Obj.create( proto );
	t.strictEqual( o.propertyIsEnumerable( 'a' ), false, 'returns expected value' );
	t.end();
});

tape( 'the `propertyIsEnumerable` prototype method returns `false` for non-existent properties', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( o.propertyIsEnumerable( 'b' ), false, 'returns expected value' );
	t.end();
});

tape( 'the `toLocaleString` prototype method returns a string', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( typeof o.toLocaleString(), 'string', 'returns expected value' );
	t.end();
});

tape( 'the `toString` prototype method returns `[object Object]`', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( Obj.prototype.toString.call( o ), '[object Object]', 'returns expected value' );
	t.end();
});

tape( 'the `toString` prototype method returns a string for other object types', function test( t ) {
	t.strictEqual( typeof Obj.prototype.toString.call( [] ), 'string', 'returns expected value' );
	t.strictEqual( typeof Obj.prototype.toString.call( null ), 'string', 'returns expected value' );
	t.strictEqual( typeof Obj.prototype.toString.call( void 0 ), 'string', 'returns expected value' );
	t.end();
});

tape( 'the `valueOf` prototype method returns the object itself', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( o.valueOf(), o, 'returns expected value' );
	t.end();
});

tape( 'the `valueOf` prototype method returns the wrapped primitive for wrapper objects', function test( t ) {
	var o;

	o = new Obj( 42 );
	t.strictEqual( o.valueOf(), 42, 'returns expected value' );

	o = new Obj( 'beep' );
	t.strictEqual( o.valueOf(), 'beep', 'returns expected value' );
	t.end();
});

tape( 'the `keys` static method returns an array of own enumerable property names', function test( t ) {
	var arr;
	var o;

	o = {
		'a': 1,
		'b': 2
	};
	arr = Obj.keys( o );
	t.deepEqual( arr.sort(), [ 'a', 'b' ], 'returns expected value' );
	t.end();
});

tape( 'the `keys` static method returns an empty array for an object with no enumerable properties', function test( t ) {
	var arr = Obj.keys( {} );
	t.deepEqual( arr, [], 'returns expected value' );
	t.end();
});

tape( 'the `create` static method creates a new object with the specified prototype', function test( t ) {
	var proto;
	var o;

	proto = {
		'a': 1
	};
	o = Obj.create( proto );
	t.strictEqual( Obj.getPrototypeOf( o ), proto, 'returns expected value' );
	t.end();
});

tape( 'the `create` static method creates a new object with `null` prototype', function test( t ) {
	var o = Obj.create( null );
	t.strictEqual( Obj.getPrototypeOf( o ), null, 'returns expected value' );
	t.end();
});

tape( 'the `defineProperty` static method defines a property on an object', function test( t ) {
	var o;

	o = Obj.defineProperty( {}, 'a', {
		'value': 1,
		'enumerable': true,
		'configurable': true,
		'writable': true
	});
	t.strictEqual( o.a, 1, 'returns expected value' );
	t.end();
});

tape( 'the `defineProperties` static method defines multiple properties on an object', function test( t ) {
	var o;

	o = Obj.defineProperties( {}, {
		'a': {
			'value': 1,
			'enumerable': true,
			'configurable': true,
			'writable': true
		},
		'b': {
			'value': 2,
			'enumerable': true,
			'configurable': true,
			'writable': true
		}
	});
	t.strictEqual( o.a, 1, 'returns expected value' );
	t.strictEqual( o.b, 2, 'returns expected value' );
	t.end();
});

tape( 'the `getOwnPropertyDescriptor` static method returns the property descriptor', function test( t ) {
	var d;
	var o;

	o = {
		'a': 1
	};
	d = Obj.getOwnPropertyDescriptor( o, 'a' );
	t.strictEqual( d.value, 1, 'returns expected value' );
	t.strictEqual( d.writable, true, 'returns expected value' );
	t.strictEqual( d.enumerable, true, 'returns expected value' );
	t.strictEqual( d.configurable, true, 'returns expected value' );
	t.end();
});

tape( 'the `getOwnPropertyDescriptor` static method returns `undefined` for non-existent properties', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( Obj.getOwnPropertyDescriptor( o, 'b' ), void 0, 'returns expected value' );
	t.end();
});

tape( 'the `getOwnPropertyNames` static method returns an array of own property names', function test( t ) {
	var arr;
	var o;

	o = {
		'a': 1,
		'b': 2
	};
	arr = Obj.getOwnPropertyNames( o );
	t.deepEqual( arr.sort(), [ 'a', 'b' ], 'returns expected value' );
	t.end();
});

tape( 'the `getOwnPropertyNames` static method includes non-enumerable properties', function test( t ) {
	var arr;
	var o;

	o = Obj.defineProperty( {}, 'a', {
		'value': 1,
		'enumerable': false,
		'configurable': true,
		'writable': true
	});
	arr = Obj.getOwnPropertyNames( o );
	t.strictEqual( arr.indexOf( 'a' ) !== -1, true, 'returns expected value' );
	t.end();
});

tape( 'the `getPrototypeOf` static method returns the prototype of an object', function test( t ) {
	var proto;
	var o;

	proto = {
		'a': 1
	};
	o = Obj.create( proto );
	t.strictEqual( Obj.getPrototypeOf( o ), proto, 'returns expected value' );
	t.end();
});

tape( 'the `getPrototypeOf` static method returns `null` for objects with a null prototype', function test( t ) {
	var o = Obj.create( null );
	t.strictEqual( Obj.getPrototypeOf( o ), null, 'returns expected value' );
	t.end();
});

tape( 'the `freeze` static method prevents modifications to an object', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	Obj.freeze( o );
	try {
		o.b = 2;
	} catch ( e ) { // eslint-disable-line no-unused-vars
		// Error expected in strict mode.
	}
	t.strictEqual( o.b, void 0, 'returns expected value' );
	t.end();
});

tape( 'the `isFrozen` static method returns `true` for frozen objects', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( Obj.isFrozen( o ), false, 'returns expected value' );
	Obj.freeze( o );
	t.strictEqual( Obj.isFrozen( o ), true, 'returns expected value' );
	t.end();
});

tape( 'the `seal` static method prevents adding or deleting properties', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	Obj.seal( o );
	try {
		o.b = 2;
	} catch ( e ) { // eslint-disable-line no-unused-vars
		// Error expected in strict mode.
	}
	t.strictEqual( o.b, void 0, 'returns expected value' );
	t.end();
});

tape( 'the `isSealed` static method returns `true` for sealed objects', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( Obj.isSealed( o ), false, 'returns expected value' );
	Obj.seal( o );
	t.strictEqual( Obj.isSealed( o ), true, 'returns expected value' );
	t.end();
});

tape( 'the `preventExtensions` static method prevents adding new properties', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	Obj.preventExtensions( o );
	try {
		o.b = 2;
	} catch ( e ) { // eslint-disable-line no-unused-vars
		// Error expected in strict mode.
	}
	t.strictEqual( o.b, void 0, 'returns expected value' );
	t.strictEqual( o.a, 1, 'existing properties are accessible' );
	t.end();
});

tape( 'the `isExtensible` static method returns `false` for non-extensible objects', function test( t ) {
	var o;

	o = {
		'a': 1
	};
	t.strictEqual( Obj.isExtensible( o ), true, 'returns expected value' );
	Obj.preventExtensions( o );
	t.strictEqual( Obj.isExtensible( o ), false, 'returns expected value' );
	t.end();
});
